# scratch: forward/inverse of the display pipeline for lin3 palette values (Neutral TM @0.86 → sRGB → grade)
import sys
import numpy as np
from scipy.optimize import least_squares

def neutral(c, exp=0.86):
    c = np.array(c, float) * exp
    x = c.min(); off = x - 6.25 * x * x if x < 0.08 else 0.04
    c = c - off
    peak = c.max(); sc = 0.76
    if peak < sc: return c
    d = 1 - sc; npk = 1 - d * d / (peak + d - sc)
    c = c * npk / peak
    g = 1 - 1 / (0.15 * (peak - npk) + 1)
    return c * (1 - g) + npk * g

def srgb(c):
    c = np.clip(c, 0, None)
    return np.where(c <= 0.0031308, 12.92 * c, 1.055 * np.power(c, 1 / 2.4) - 0.055)

def grade(c, sat=1.36, con=1.15):
    l = c @ np.array([0.2126, 0.7152, 0.0722])
    c = l + (c - l) * sat
    return np.clip((c - 0.5) * con + 0.5, 0, 1)

def fwd(lin): return grade(srgb(neutral(lin))) * 255

def inv(target):
    t = np.array(target, float)
    r = least_squares(lambda x: fwd(np.abs(x)) - t, x0=np.full(3, 0.5), bounds=(0, 4))
    return r.x, fwd(r.x)

if __name__ == '__main__':
    for a in sys.argv[1:]:
        v = [float(x) for x in a.split(',')]
        if all(x <= 4 for x in v) and any(x % 1 for x in v):
            print('fwd', v, '->', np.round(fwd(v)).astype(int))
        else:
            x, f = inv(v); print('inv', v, '-> lin3(%.4f, %.4f, %.4f)' % tuple(x), 'check', np.round(f).astype(int))
